window.AttemptUI={color:r=>r.blank?'score-blank':r.score>=r.maximum?'score-full':r.score>0?'score-partial':'score-zero',label:r=>r.blank?'Unanswered':r.score+' / '+r.maximum+' points',legend:()=>'<div class="score-legend"><span class="score-full">Full score</span><span class="score-partial">Partial score</span><span class="score-zero">Zero or negative score</span><span class="score-blank">Unanswered</span></div>',duration:ms=>{const s=Math.floor(ms/1000);return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s/60)%60).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}};

// Shared summary for the current result and saved attempt history.
AttemptUI.scenarioSummary=(questions,result)=>{
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const groups=new Map();questions.forEach((q,i)=>{if(!q.case_id)return;if(!groups.has(q.case_id))groups.set(q.case_id,{title:q.case?.title||q.case_id,items:[]});groups.get(q.case_id).items.push({q,r:result.items[i]})});
 const missed=[...groups].filter(([cid,g])=>g.items.some(({r})=>r.blank||r.score<r.maximum)).map(([cid])=>cid);
 return '<section class="scenario-results"><h2>Results by scenario</h2>'+[...groups].map(([cid,g])=>`<details open><summary><strong>${escape(cid)} — ${escape(g.title)}</strong> · ${Math.round(g.items.reduce((n,{r})=>n+r.score,0)*100)/100} / ${g.items.reduce((n,{r})=>n+r.maximum,0)} points</summary><ul>${g.items.map(({q,r})=>`<li><strong>${escape(q.display_label||q.id)}: ${r.score} / ${r.maximum}</strong> — ${RichText.inline(q.text)}<details><summary>Explanation</summary><div>${RichText.render(q.explanation||'No explanation supplied.')}</div></details></li>`).join('')}</ul></details>`).join('')+(missed.length?`<p><a class="secondary" href="/?set=1&mode=case_scenarios&cases=${encodeURIComponent(missed.join(','))}">Retry missed scenarios (${missed.length})</a></p><p class="hint">Retries use the latest published questions and create a new saved attempt. Previous results remain unchanged.</p>`:'<p>Full credit in every scenario.</p>')+'</section>';
};
